from pathlib import Path
p = Path('pipeline/ingest.py')
s = p.read_text()
start = s.index('def _literal_set(tree, name):')
end = s.index('\ndef init_db(conn):', start)
new = r'''SAFE_VENDOR_BUILTINS = {
    "abs": abs,
    "all": all,
    "any": any,
    "bool": bool,
    "dict": dict,
    "float": float,
    "int": int,
    "len": len,
    "list": list,
    "max": max,
    "min": min,
    "set": set,
    "str": str,
    "tuple": tuple,
}


class UnsafeVendorRule(ValueError):
    """A vendor rule pack used syntax outside the supported safe subset."""


def _check_assignment_target(target):
    if isinstance(target, ast.Name):
        if target.id.startswith("__"):
            raise UnsafeVendorRule("dunder names are not allowed")
        return
    if isinstance(target, (ast.Tuple, ast.List)):
        for item in target.elts:
            _check_assignment_target(item)
        return
    raise UnsafeVendorRule("vendor rules may only assign to local names")


def _validate_vendor_ast(tree):
    """Ensure a rule pack only contains side-effect-limited check code."""
    function_names = {
        node.name for node in tree.body if isinstance(node, ast.FunctionDef)
    }
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom, ast.Global, ast.Nonlocal,
                             ast.ClassDef, ast.With, ast.AsyncWith,
                             ast.AsyncFunctionDef, ast.Delete)):
            raise UnsafeVendorRule(f"unsupported vendor rule syntax: {type(node).__name__}")
        if isinstance(node, ast.FunctionDef):
            if node.name.startswith("__"):
                raise UnsafeVendorRule("dunder function names are not allowed")
            if node.decorator_list:
                raise UnsafeVendorRule("decorators are not allowed in vendor rules")
        if isinstance(node, ast.Assign):
            for target in node.targets:
                _check_assignment_target(target)
        if isinstance(node, ast.AnnAssign):
            _check_assignment_target(node.target)
        if isinstance(node, ast.AugAssign):
            _check_assignment_target(node.target)
        if isinstance(node, ast.Attribute) and node.attr.startswith("__"):
            raise UnsafeVendorRule("dunder attributes are not allowed")
        if isinstance(node, ast.Name) and node.id.startswith("__"):
            raise UnsafeVendorRule("dunder names are not allowed")
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            if node.func.id not in SAFE_VENDOR_BUILTINS and node.func.id not in function_names:
                raise UnsafeVendorRule(f"call to {node.func.id!r} is not allowed")


def _load_safe_extra_checks(path):
    """Return extra_checks from a vendor rule pack without giving it authority."""
    tree = ast.parse(path.read_text(), filename=str(path))
    _validate_vendor_ast(tree)
    namespace = {"__builtins__": SAFE_VENDOR_BUILTINS}
    exec(compile(tree, str(path), "exec"), namespace, namespace)
    fn = namespace.get("extra_checks")
    return fn if callable(fn) else None


def load_vendor_rules(rules_dir):
    """Load optional per-vendor checks without importing trusted modules.

    Rule packs are vendor-supplied, so they are treated as data/code in a small
    restricted subset. They may add row rejection checks via extra_checks(row),
    but they cannot import operator modules, mutate schema/policy, or grant
    privileges.
    """
    checks = []
    directory = Path(rules_dir)
    if not directory.is_dir():
        return checks
    for path in sorted(directory.glob("*_rules.py")):
        try:
            fn = _load_safe_extra_checks(path)
        except (OSError, SyntaxError, UnsafeVendorRule, ValueError):
            # Optional vendor packs must not crash ingestion or gain authority.
            # Unsupported packs are ignored rather than treated as policy.
            continue
        if callable(fn):
            checks.append((path.name, fn))
    return checks
'''
